const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const html=fs.readFileSync('index.html','utf8');test('DATA-07: lineups explicitly distinguish projections from confirmed lineups',()=>{assert.ok(html.includes('Historická projekce, nikoli potvrzená sestava'));assert.ok(html.includes('Nedávná projekce, nikoli potvrzená sestava'));assert.ok(html.includes('Aktuálnost neověřena'));assert.ok(html.includes('safe(trustLabel)'));});test('DATA-07: goalie source age and evidence status are visible',()=>{assert.ok(html.includes("min zpět"));assert.ok(html.includes('Pouze předpoklad zdroje'));assert.ok(html.includes('Potvrzení zdrojem'));});